package main

import (
	"encoding/json"
	"os"
	"strings"
	"testing"
)

func TestOrderingProfile(t *testing.T) {
	var fixtures struct {
		Cases []struct {
			FEN string `json:"fen"`
		} `json:"cases"`
	}
	data, err := os.ReadFile("/Users/philyawj/projects/Pandafish/tools/benchmark/live/v0.10-twitch-m2-20261112/analysis/stockfish-n500000-confirmed/regression-candidates.json")
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(data, &fixtures); err != nil {
		t.Fatal(err)
	}
	commands := []string{"startpos", "fen " + timeoutPosition, "fen " + queenRaidPosition, "fen " + crowdedPosition}
	for _, p := range fixtures.Cases {
		commands = append(commands, "fen "+p.FEN)
	}
	type result struct {
		Position string `json:"position"`
		Depth    int    `json:"depth"`
		Nodes    uint64 `json:"nodes"`
		Cutoffs  uint64 `json:"cutoffs"`
		Quiet    uint64 `json:"quiet_cutoffs"`
		Repeated uint64 `json:"repeated_quiet_move_at_same_remaining_depth"`
	}
	rows := []result{}
	for _, command := range commands {
		g, err := parsePosition(strings.Fields(command))
		if err != nil {
			t.Fatal(err)
		}
		profileCutoffs, profileQuiet, profileRepeated = 0, 0, 0
		profileSeen = [maxSearchDepth + 1]map[uint16]bool{}
		w := searcher{table: newTable()}
		if _, _, ok := w.root(g.Position(), rootMoves(g.Position(), nil), 4); !ok {
			t.Fatal("incomplete")
		}
		rows = append(rows, result{command, 4, w.nodes, profileCutoffs, profileQuiet, profileRepeated})
	}
	b, err := json.MarshalIndent(rows, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err = os.WriteFile("/tmp/pandafish-v012-baseline-profile.json", append(b, '\n'), 0644); err != nil {
		t.Fatal(err)
	}
}
